import * as React from 'react';
import { expect, it, describe, vi, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';
import { FieldControl as OldControl } from './OldFieldControl';

afterEach(cleanup);

const variants = [
  ['old', OldControl],
  ['new', Field.Control],
] as const;

describe.each(variants)('%s', (label, Control: any) => {
  it('post-submit reset of required controlled field', async () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form onFormSubmit={() => setValue('')}>
          <Field.Root name="message" data-testid="root">
            <Control required value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="submit">send</button>
        </Form>
      );
    }
    render(<App />);
    const input = screen.getByRole('textbox');
    fireEvent.change(input, { target: { value: 'hello' } });
    fireEvent.click(screen.getByText('send'));
    await act(async () => {});
    console.log(label, 'post-submit reset: invalid=', screen.getByTestId('root').hasAttribute('data-invalid'), 'error=', screen.queryByTestId('error')?.textContent, 'value=', (input as HTMLInputElement).value, 'dirty=', screen.getByTestId('root').hasAttribute('data-dirty'));
  });

  it('control swap leaves filled stale', async () => {
    function App() {
      const [mode, setMode] = React.useState('a');
      return (
        <Field.Root data-testid="root">
          {mode === 'a' ? (
            <Control key="a" value="x" onValueChange={() => {}} />
          ) : (
            <Control key="b" value="" onValueChange={() => {}} />
          )}
          <button onClick={() => setMode('b')}>swap</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('swap'));
    console.log(label, 'swap: filled=', screen.getByTestId('root').hasAttribute('data-filled'));
  });

  it('value null', async () => {
    const validate = vi.fn(() => null);
    const spy = vi.spyOn(console, 'error').mockImplementation(() => {});
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Control value={null as any} onValueChange={() => {}} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
    const root = screen.getByTestId('root');
    console.log(label, 'null: filled=', root.hasAttribute('data-filled'), 'dirty=', root.hasAttribute('data-dirty'), 'validate calls=', validate.mock.calls.length, 'dom=', (screen.getByRole('textbox') as HTMLInputElement).value);
    spy.mockRestore();
  });

  it('disabled control programmatic change', async () => {
    const validate = vi.fn(() => 'bad');
    function App() {
      const [value, setValue] = React.useState('foo');
      const [disabled, setDisabled] = React.useState(true);
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Control disabled={disabled} value={value} onValueChange={setValue} />
          <button onClick={() => setValue('bar')}>set</button>
          <button onClick={() => setDisabled(false)}>enable</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('set'));
    const root = screen.getByTestId('root');
    console.log(label, 'disabled: dirty=', root.hasAttribute('data-dirty'), 'invalid=', root.hasAttribute('data-invalid'), 'validate calls=', validate.mock.calls.length);
    fireEvent.click(screen.getByText('enable'));
    console.log(label, 'after enable: dirty=', root.hasAttribute('data-dirty'), 'invalid=', root.hasAttribute('data-invalid'));
  });

  it('render count controlled onChange mode', async () => {
    let count = 0;
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={() => null}>
          <Control
            data-testid="control"
            value={value}
            onValueChange={setValue}
            render={(props: any) => {
              count += 1;
              return <input {...props} />;
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control');
    fireEvent.change(control, { target: { value: 'a' } });
    const settled = count;
    fireEvent.change(control, { target: { value: 'ab' } });
    fireEvent.change(control, { target: { value: 'abc' } });
    console.log(label, 'renders for 2 keystrokes (onChange mode)=', count - settled);
  });

  it('checkbox type with value', async () => {
    function App() {
      return (
        <Form>
          <Field.Root name="agree" data-testid="root">
            <Control type="checkbox" value="yes" required data-testid="cb" />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="submit">send</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('send'));
    const root = screen.getByTestId('root');
    console.log(label, 'checkbox after submit: invalid=', root.hasAttribute('data-invalid'));
    fireEvent.click(screen.getByTestId('cb'));
    console.log(label, 'checkbox after check: invalid=', root.hasAttribute('data-invalid'), 'checked=', (screen.getByTestId('cb') as HTMLInputElement).checked, 'error=', screen.queryByTestId('error')?.textContent);
  });

  it('array value validate arg', async () => {
    const validate = vi.fn((_v: unknown) => null);
    function App() {
      const [value, setValue] = React.useState<string[]>(['a', 'b']);
      return (
        <Form>
          <Field.Root name="multi" validate={validate}>
            <Control
              value={value}
              onChange={(e: any) => setValue(Array.from(e.target.selectedOptions, (o: any) => o.value))}
              render={
                <select multiple>
                  <option value="a">a</option>
                  <option value="b">b</option>
                  <option value="c">c</option>
                </select>
              }
            />
          </Field.Root>
          <button type="submit">send</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('send'));
    console.log(label, 'array validate arg=', JSON.stringify(validate.mock.calls.map((c) => c[0])));
  });

  it('async loaded initial value', async () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={(v) => (String(v).length < 10 ? 'too short' : null)}>
          <Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="error" />
          <button onClick={() => setValue('loaded')}>load</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('load'));
    const root = screen.getByTestId('root');
    console.log(label, 'async load: dirty=', root.hasAttribute('data-dirty'), 'invalid=', root.hasAttribute('data-invalid'), 'error=', screen.queryByTestId('error')?.textContent, 'touched=', root.hasAttribute('data-touched'));
  });

  it('server error wiped on programmatic change', async () => {
    function App() {
      const [value, setValue] = React.useState('secret');
      return (
        <Form errors={{ password: 'Wrong password' }}>
          <Field.Root name="password" data-testid="root">
            <Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="button" onClick={() => setValue('')}>clear</button>
        </Form>
      );
    }
    render(<App />);
    console.log(label, 'server error before=', screen.queryByTestId('error')?.textContent);
    fireEvent.click(screen.getByText('clear'));
    console.log(label, 'server error after programmatic clear=', screen.queryByTestId('error')?.textContent);
  });

  it('controlled prevented change', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message" validationMode="onChange" validate={validate}>
            <Control value={value} onValueChange={(v: string, d: any) => { d.cancel(); setValue(v); }} />
            <Field.Error data-testid="error" />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), { capture: true, once: true });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    console.log(label, 'controlled prevented+canceled: validate calls=', validate.mock.calls.length, 'error=', screen.queryByTestId('error')?.textContent);
  });
});
EOF
