  it('server error wiped on programmatic change (stable errors)', async () => {
    function App() {
      const [value, setValue] = React.useState('secret');
      return (
        <Form errors={ERR}>
          <Field.Root name="password" data-testid="root">
            <Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="button" onClick={() => setValue('')}>clear</button>
        </Form>
      );
    }
    render(<App />);
    log(label, 'server error before=', screen.queryByTestId('error')?.textContent);
    fireEvent.click(screen.getByText('clear'));
    log(label, 'server error after programmatic clear=', screen.queryByTestId('error')?.textContent);
  });

  it('errors and value set in same batch', async () => {
    function App() {
      const [value, setValue] = React.useState('secret');
      const [errors, setErrors] = React.useState({});
      return (
        <Form errors={errors}>
          <Field.Root name="password" data-testid="root">
            <Control value={value} onValueChange={setValue} />
            <Field.Error data-testid="error" />
          </Field.Root>
          <button type="button" onClick={() => { setErrors(ERR); setValue(''); }}>fail</button>
        </Form>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByText('fail'));
    log(label, 'same batch errors+value: error=', screen.queryByTestId('error')?.textContent);
  });

  it('controlled prevented change (stable errors)', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={ERR}>
          <Field.Root name="password" validationMode="onChange" validate={validate}>
            <Control value={value} onValueChange={(v: string) => setValue(v)} />
            <Field.Error data-testid="error" />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    control.addEventListener('input', (event) => event.preventDefault(), { capture: true, once: true });
    fireEvent.input(control, { cancelable: true, target: { value: 'a' } });
    log(label, 'controlled prevented: validate calls=', validate.mock.calls.length, 'error=', screen.queryByTestId('error')?.textContent);
  });

  it('controlled canceled (stable errors)', async () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={ERR}>
          <Field.Root name="password" validationMode="onChange" validate={validate}>
            <Control value={value} onValueChange={(v: string, d: any) => { d.cancel(); setValue(v); }} />
            <Field.Error data-testid="error" />
          </Field.Root>
        </Form>
      );
    }
    render(<App />);
    const control = screen.getByRole<HTMLInputElement>('textbox');
    fireEvent.change(control, { target: { value: 'a' } });
    log(label, 'controlled canceled: validate calls=', validate.mock.calls.length, 'error=', screen.queryByTestId('error')?.textContent);
  });

  it('uncontrolled canceled: dirty/filled', async () => {
    render(
      <Field.Root data-testid="root">
        <Control onValueChange={(v: string, d: any) => d.cancel()} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    log(label, 'uncontrolled canceled: dirty=', root.hasAttribute('data-dirty'), 'filled=', root.hasAttribute('data-filled'));
  });

  it('reset to new baseline after load then user edits back', async () => {
    function App() {
      const [value, setValue] = React.useState('');
