        <Field.Root data-testid="root">
          <Control value={value} onValueChange={setValue} />
          <button onClick={() => setValue('')}>clear</button>
        </Field.Root>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
    fireEvent.click(screen.getByText('clear'));
    log(label, 'clear button: dirty=', root.hasAttribute('data-dirty'), 'filled=', root.hasAttribute('data-filled'));
  });

  it('non-input render element controlled mount filled', async () => {
    const Custom = React.forwardRef<HTMLDivElement, any>((props, ref) => {
      const { value, onChange, ...rest } = props;
      return <div ref={ref} data-value={value} {...rest} />;
    });
