      <Field.Root data-testid="root">
        <Control value="x" onValueChange={() => {}} render={<Custom />} />
      </Field.Root>,
    );
    log(label, 'custom render mount filled=', screen.getByTestId('root').hasAttribute('data-filled'));
  });
});
